package io.knowledgebrain.space;
import java.time.Clock;
import java.util.*;
import java.util.concurrent.*;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.assertj.core.api.Assertions.*;
import io.knowledgebrain.contracts.space.group.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_SPACE_DATABASE_URL",matches=".+")
class GroupSpaceIntegrationTest {
 PGSimpleDataSource source;JdbcTemplate jdbc;GroupSpaceStore store;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID owner,group;String trace="a".repeat(32);
 @BeforeEach void setup(){source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_SPACE_DATABASE_URL"));source.setUser("brain_space");source.setPassword(System.getenv("BRAIN_TEST_SPACE_DATABASE_PASSWORD"));Flyway.configure().dataSource(source).load().migrate();jdbc=new JdbcTemplate(source);store=new GroupSpaceStore(source,Clock.systemUTC());owner=ids.next();group=ids.next();}
 @Test void reviewCapabilityPinsCurrentMembershipAndNeverSelectsOtherRecipient(){var g=store.provision(group,owner,trace);assertThat(store.reviewAccess(group,owner).membershipVersion()).isEqualTo(1);assertThat(store.reviewAccess(group,owner).principalId()).isEqualTo(owner);var other=ids.next();assertThatThrownBy(()->store.reviewAccess(group,other)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);jdbc.update("UPDATE space_membership SET role='VIEWER',group_version=2 WHERE space_id=? AND principal_id=?",g.spaceId(),owner);assertThat(store.reviewAccess(group,owner).membershipVersion()).isEqualTo(2);jdbc.update("UPDATE space_membership SET state='RETIRED',group_version=3 WHERE space_id=? AND principal_id=?",g.spaceId(),owner);assertThatThrownBy(()->store.reviewAccess(group,owner)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);}
 @Test void createsOnlyPrivateGroupSpaceWithOwnerAndOutbox()throws Exception{var g=store.provision(group,owner,trace);assertThat(g.spaceId().version()).isEqualTo(7);assertThat(g.visibility()).isEqualTo("PRIVATE");assertThat(g.role()).isEqualTo("OWNER");var envelope=EventEnvelopeV1.parseFrom(jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,g.spaceId()));var p=GroupSpaceCreatedPayloadV1.parseFrom(envelope.getPayload());assertThat(p.getGroupId()).isEqualTo(group.toString());assertThat(p.getKind()).isEqualTo("GROUP");assertThat(envelope.getSpaceId()).isEqualTo(g.spaceId().toString());assertThat(envelope.getTraceId()).isEqualTo(trace);assertThat(new PersonalSpaceStore(source,Clock.systemUTC()).owned(owner)).isEmpty();}
 @Test void replayAfterRestartAndConcurrencyNeverDuplicate()throws Exception{try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var tasks=new ArrayList<Future<GroupSpaceStore.Grant>>();for(int i=0;i<6;i++)tasks.add(executor.submit(()->new GroupSpaceStore(source,Clock.systemUTC()).provision(group,owner,trace)));var spaces=new HashSet<UUID>();for(var task:tasks)spaces.add(task.get(20,TimeUnit.SECONDS).spaceId());assertThat(spaces).hasSize(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Long.class,spaces.iterator().next())).isEqualTo(1);}}
 @Test void otherOwnerAndRevokedMembershipCannotRegrant(){var g=store.provision(group,owner,trace);assertThat(store.access(ids.next(),List.of(group))).isEmpty();assertThatThrownBy(()->store.provision(group,ids.next(),trace)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);jdbc.update("UPDATE space_membership SET state='RETIRED' WHERE space_id=? AND principal_id=?",g.spaceId(),owner);assertThat(store.access(owner,List.of(group))).isEmpty();assertThatThrownBy(()->store.provision(group,owner,trace)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);assertThat(jdbc.queryForObject("SELECT state FROM space_membership WHERE space_id=? AND principal_id=?",String.class,g.spaceId(),owner)).isEqualTo("RETIRED");}
 @Test void retiredSpaceOrChangedRoleNeverGrants(){var g=store.provision(group,owner,trace);jdbc.update("UPDATE space_membership SET role='VIEWER' WHERE space_id=? AND principal_id=?",g.spaceId(),owner);assertThat(store.access(owner,List.of(group))).isEmpty();jdbc.update("UPDATE space SET state='RETIRED' WHERE space_id=?",g.spaceId());assertThatThrownBy(()->store.provision(group,owner,trace)).isInstanceOf(org.springframework.web.server.ResponseStatusException.class);}
 @Test void outboxFailureRollsBackSpaceMembershipAndMapping(){assertThatThrownBy(()->store.provision(group,owner,"0".repeat(32))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM group_space_origin WHERE group_id=?",Long.class,group)).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM space WHERE owner_principal_id=?",Long.class,owner)).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM space_membership WHERE principal_id=?",Long.class,owner)).isZero();assertThat(store.provision(group,owner,trace)).isNotNull();}
}
